import{_ as s,a0 as a,w as i,s as l,ao as u,I as r,x as p,a1 as e,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"在Ubuntu中使用终端删除应用程序 | LCTT x X-CMD","titleTemplate":false,"description":"在Ubuntu中使用终端删除应用程序 | LCTT (201309) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在Ubuntu中使用终端删除应用程序 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在Ubuntu中使用终端删除应用程序 | LCTT (201309) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201309/Removing Applications Using Terminal in Ubuntu","title":"在Ubuntu中使用终端删除应用程序","tag":"201309","desc":""},"relativePath":"201309/Removing Applications Using Terminal in Ubuntu.md","filePath":"[post].md"}'),d={name:"201309/Removing Applications Using Terminal in Ubuntu.md"};function g(m,t,c,T,x,b){const n=a("Link");return i(),l("div",null,[t[11]||(t[11]=u(`<h1 id="在ubuntu中使用终端删除应用程序" tabindex="-1">在Ubuntu中使用终端删除应用程序 <a class="header-anchor" href="#在ubuntu中使用终端删除应用程序" aria-label="Permalink to “在Ubuntu中使用终端删除应用程序”">​</a></h1><p>作为一个Linux（Ubuntu)用户，你每次从终端安装应用程序的时候都会用到<strong>apt-get</strong>这条命令。</p><p>虽然可以使用图形化界面来安装删除应用程序，但是命令行依然被认为是功能强大的方式。在安装了许多大大小小的应用程序以后，你会需要更多的磁盘空间来安装其他的应用程序，或者有些程序对你不再有用了。</p><p>大多数人，尤其是初学者，通过在查阅资料后，能够从终端安装一个程序，但是却很难删除它。我也曾经有过这样的经历。</p><p>这是一个简单的教程，指导你如何删除已经安装的软件包。</p><p>a. 打开终端（ctrl + alt + t）</p><p>b. 输入</p><pre><code>$ dpkg --list
</code></pre><p>（这条命令会显示所有已安装的包）</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/09/list_.png" alt=""></p><p>或者</p><pre><code>$ dpkg --list | less
</code></pre><p>（这样可以轻松的使用用户密钥来导航）</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/09/dpkg_list.png" alt=""></p><p>或者</p><p>如果你知道软件包的名字，你可以使用管道命令<strong>grep</strong>来查找，使用下面的语句：</p><pre><code>$ dpkg --list|grep -i  &#39;packagename&#39;
</code></pre><p>以<strong>VLC</strong>播放器为例。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/09/vlc_grep.png" alt=""></p><p>c. 查找要删除的包名字，这里我要使用<strong>sox</strong>。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/09/remove_SoX.png" alt=""></p><p>d. 只删除一个软件包，使用下面的命令：</p><pre><code>$ sudo apt-get remove &lt;packagename&gt;
</code></pre><p>比如，删除一个叫<strong>sox</strong>的软件包，输入：</p><pre><code>$ sudo apt-get remove sox
</code></pre><p>输入y来确认卸载。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/09/sox2.png" alt=""></p><p>e. 要删除一个包以及它的配置文件，输入：</p><pre><code>$ sudo apt-get --purge remove &lt;packagename&gt;
</code></pre><p>比如，删除一个叫sox的包以及其所有的配置文件：</p><pre><code>$ sudo apt-get --purge remove sox
</code></pre>`,31)),r("p",null,[t[1]||(t[1]=p("via: ",-1)),e(n,{href:"http://www.unixmen.com/removing-applications-using-terminal-ubuntu/"},{default:o(()=>[...t[0]||(t[0]=[p("http://www.unixmen.com/removing-applications-using-terminal-ubuntu/",-1)])]),_:1})]),r("p",null,[t[4]||(t[4]=p("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[2]||(t[2]=[p("LCTT",-1)])]),_:1}),t[5]||(t[5]=p(" 原创翻译，",-1)),e(n,{href:"http://linux.cn/portal.php"},{default:o(()=>[...t[3]||(t[3]=[p("Linux中国",-1)])]),_:1}),t[6]||(t[6]=p(" 荣誉推出",-1))]),r("p",null,[t[9]||(t[9]=p("译者：",-1)),e(n,{href:"http://linux.cn/space/markvv"},{default:o(()=>[...t[7]||(t[7]=[p("markvv",-1)])]),_:1}),t[10]||(t[10]=p(" 校对：",-1)),e(n,{href:"http://linux.cn/space/14763"},{default:o(()=>[...t[8]||(t[8]=[p("Caroline",-1)])]),_:1})])])}const U=s(d,[["render",g]]);export{C as __pageData,U as default};
